package cn.sifangguan.hotelaios.finance;
import cn.sifangguan.hotelaios.shared.audit.AuditWriter;
import cn.sifangguan.hotelaios.shared.context.TenantPrincipal;
import cn.sifangguan.hotelaios.shared.db.TenantDatabaseContext;
import cn.sifangguan.hotelaios.shared.security.*;
import cn.sifangguan.hotelaios.storeassets.*;
import jakarta.validation.constraints.*;
import org.springframework.jdbc.core.namedparam.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import java.time.*;
import java.util.*;
import static cn.sifangguan.hotelaios.finance.FinanceV2Support.*;

/** Real source services remain authoritative. Archive grants never substitute for their read/original permissions. */
@Service @Transactional
public class FinanceArchiveExtendedSources {
 public static final Set<String> TYPES=Set.of("SUPPLY_RECOGNITION","ASSET_CARD","ACCRUAL","ASSET_GAIN","BOOK_REPORT");
 public record ReportSource(@NotNull UUID requestId,@NotNull UUID bookId,@NotBlank String month,@NotBlank String expectedReportVersion){}
 private final NamedParameterJdbcTemplate jdbc;private final TenantDatabaseContext db;private final AccessPolicy access;private final AuditWriter audit;private final FinanceSupplyService supply;private final FinanceAccrualControlService accrual;private final FinanceAssetGainService gains;private final FinanceAssetGainEvidenceService gainFiles;private final FinanceAccountingService accounting;private final FinanceOperationsService operations;private final FinanceService claims;private final FinanceEvidenceService files;private final FinanceOperationsEvidenceService operationFiles;private final FinanceMigrationService migration;private final ProcurementService procurement;private final ProcurementEvidenceService procurementFiles;
 public FinanceArchiveExtendedSources(NamedParameterJdbcTemplate jdbc,TenantDatabaseContext db,AccessPolicy access,AuditWriter audit,FinanceSupplyService supply,FinanceAccrualControlService accrual,FinanceAssetGainService gains,FinanceAssetGainEvidenceService gainFiles,FinanceAccountingService accounting,FinanceOperationsService operations,FinanceService claims,FinanceEvidenceService files,FinanceOperationsEvidenceService operationFiles,FinanceMigrationService migration,ProcurementService procurement,ProcurementEvidenceService procurementFiles){this.jdbc=jdbc;this.db=db;this.access=access;this.audit=audit;this.supply=supply;this.accrual=accrual;this.gains=gains;this.gainFiles=gainFiles;this.accounting=accounting;this.operations=operations;this.claims=claims;this.files=files;this.operationFiles=operationFiles;this.migration=migration;this.procurement=procurement;this.procurementFiles=procurementFiles;}
 private TenantPrincipal prepare(){access.requireAnyPermission("finance.archive.read","finance.archive.grant");var p=access.principal();db.apply(p.tenantId());return p;}
 private Map<String,Object> one(String sql,MapSqlParameterSource b){var rows=jdbc.queryForList(sql,b);if(rows.size()!=1)throw missing();return rows.getFirst();}
 public Map<String,Object> sourceDetail(String type,UUID source){var p=prepare();return switch(type){
  case "SUPPLY_RECOGNITION"->{var row=one("select receipt_id from fs_recognition where tenant_id=:tenant and id=:id",base(p).addValue("id",source));var detail=output(supply.receipt(id(row.get("receipt_id"))));detail.remove("invoices"); // Available invoices are not the invoices actually used by this source.
   var rec=map(detail.get("recognition"));if(!source.equals(id(rec.get("id"))))throw conflict("采购确认与原复核批次不一致");detail.put("id",source);detail.put("companyId",rec.get("companyId"));detail.put("version",rec.get("version"));detail.put("status",rec.get("status"));yield detail;}
  case "ASSET_CARD"->output(supply.asset(source));case "ACCRUAL"->output(accrual.detail(source));case "ASSET_GAIN"->output(gains.detail(source));case "BOOK_REPORT"->bookReport(p,source);
  case "INTAKE"->claims.intakeDetail(source);case "PROCUREMENT"->output(procurement.detail(source));case "OPERATION"->operations.detail(source);case "MIGRATION"->migration.detail(source);default->throw bad("专项档案来源无效");};}
 public Map<String,Object> resolve(String type,UUID source){var p=prepare();var detail=sourceDetail(type,source);UUID hotel=id(detail.get("hotelId")),company=id(detail.get("companyId"));if(hotel==null||company==null)throw conflict("专项来源缺少冻结组织或法人，不能猜测归档");access.requireOrgScope(hotel);var graph=new ArrayList<Map<String,Object>>();var required=new ArrayList<Map<String,Object>>();var originals=new HashSet<String>();String version=type+":"+Objects.toString(detail.get("version"),Objects.toString(detail.get("reportVersion"),"0"))+":"+Objects.toString(detail.get("status"),"");graph.add(node(type,source,"SOURCE",version));
  collect(type,source,detail,graph,required,originals,0);
  String eventType=switch(type){case "SUPPLY_RECOGNITION"->"FS_PROCUREMENT";case "ACCRUAL"->"FAR_ACCRUAL";case "ASSET_GAIN"->"FS_ASSET_GAIN";default->"NO_DIRECT_SOURCE_EVENT";};
  var events=jdbc.queryForList("select id,hotel_id,company_id,source_type,source_id,event_key,status,voucher_id,request_hash,metadata from fa_source_event where tenant_id=:tenant and source_type=:eventType and (source_id=:id or metadata->>'businessId'=cast(:id as text) or metadata->>'assetId'=cast(:id as text) or metadata->>'planId'=cast(:id as text)) order by id",base(p).addValue("id",source).addValue("eventType",eventType));
  for(var event:events){access.requireOrgScope(id(event.get("hotel_id")));if(event.get("company_id")!=null&&!company.equals(id(event.get("company_id"))))throw conflict("专项档案的实际会计来源法人不一致");graph.add(node("ACCOUNTING_SOURCE",id(event.get("id")),"REAL_SOURCE_EVENT",event.get("request_hash").toString()));if(event.get("voucher_id")!=null){UUID voucher=id(event.get("voucher_id"));var data=accounting.voucher(voucher);graph.add(node("VOUCHER",voucher,"POSTED_OR_DRAFT_VOUCHER",data.get("version")+":"+data.get("status")));required.add(Map.of("type","VOUCHER","id",voucher));}}
  for(String field:List.of("events","runs"))for(var actual:rows(detail.getOrDefault(field,List.of())))if(actual.get("voucherId")!=null){UUID voucher=id(actual.get("voucherId"));if(graph.stream().noneMatch(n->"VOUCHER".equals(n.get("type"))&&voucher.equals(n.get("id")))){var data=accounting.voucher(voucher);graph.add(node("VOUCHER",voucher,"POSTED_OR_DRAFT_VOUCHER",data.get("version")+":"+data.get("status")));required.add(Map.of("type","VOUCHER","id",voucher));}}
  if(type.equals("BOOK_REPORT"))graph.add(node("BOOK_REPORT",id(detail.get("bookId")),"EXACT_FROZEN_REPORT_VERSION",detail.get("reportVersion").toString()));String hash=FinanceArchiveSources.canonicalHash(Map.of("payload",clean(detail),"graph",graph,"events",clean(output(Map.of("items",events)).get("items"))));version+=":"+hash;graph.getFirst().put("version",version);
  var result=new LinkedHashMap<String,Object>();result.put("sourceType",type);result.put("sourceId",source);result.put("sourceVersion",version);result.put("hotelIds",List.of(hotel));result.put("companyIds",List.of(company));result.put("payload",clean(detail));result.put("graph",graph);result.put("requiredSources",required);result.put("events",clean(output(Map.of("items",events)).get("items")));result.put("sensitivePayroll",Boolean.TRUE.equals(detail.get("sensitivePayroll")));result.put("lineageNote","专项真实原单、实际来源及不可变原件逐项关联；已关账三表不依赖AI。每次调阅仍重查所有原来源及原件授权，不凭归档批准扩大权限。");return result;
 }
 private void collect(String type,UUID id,Map<String,Object> detail,List<Map<String,Object>> graph,List<Map<String,Object>> required,Set<String> originals,int depth){if(depth>5)throw conflict("专项来源关系超过受控层数，请人工核对，未省略原件来源");
  if(type.equals("ASSET_GAIN"))for(var file:rows(detail.get("originals")))original(graph,file,"ASSET_GAIN",id,originals);
  if(type.equals("OPERATION")){for(var file:rows(detail.getOrDefault("attachments",List.of())))original(graph,file,"OPERATION",id,originals);if("FS_PROCUREMENT".equals(detail.get("sourceType"))&&detail.get("sourceId")!=null)linked("SUPPLY_RECOGNITION",FinanceV2Support.id(detail.get("sourceId")),graph,required,originals,depth);}
  if(type.equals("SUPPLY_RECOGNITION")){var rec=map(detail.get("recognition"));Object invoiceIds=rec.get("invoiceIds");if(invoiceIds instanceof List<?> list)for(Object invoice:list){UUID intake=FinanceV2Support.id(invoice);claims.intakeDetail(intake);var file=claims.intakeOriginal(intake);var used=one("select sha256 from fs_invoice_use where tenant_id=:tenant and recognition_id=:recognition and invoice_id=:invoice",base(access.principal()).addValue("recognition",id).addValue("invoice",intake));if(!Objects.equals(used.get("sha256"),file.get("sha256")))throw conflict("原采购实际占用与收票原件哈希不一致，不能归档其他票代替");var entry=new LinkedHashMap<>(file);entry.put("id",intake);original(graph,entry,"INTAKE",intake,originals);required.add(Map.of("type","INTAKE","id",intake));}
   if(detail.get("orderId")!=null){UUID order=FinanceV2Support.id(detail.get("orderId"));try{var orderDetail=output(procurement.detail(order));required.add(Map.of("type","PROCUREMENT","id",order));graph.add(node("PROCUREMENT",order,"ACTUAL_SOURCE_DOCUMENT",Objects.toString(orderDetail.get("version"),Objects.toString(orderDetail.get("rowVersion"),"0"))));for(var file:rows(orderDetail.getOrDefault("attachments",List.of()))){UUID attachment=FinanceV2Support.id(file.get("id"));var full=output(procurement.attachment(order,attachment));original(graph,full,"PROCUREMENT",order,originals);}}catch(AccessDeniedException denied){graph.add(node("SOURCE_ACCESS_REQUIRED",order,"ORIGINAL_PERMISSION_NOT_GRANTED","需原采购权限后调阅，不以财务菜单绕过"));}}
  }
  if(type.equals("ASSET_CARD")){if(detail.get("sourceDocumentId")!=null)linked("OPERATION",FinanceV2Support.id(detail.get("sourceDocumentId")),graph,required,originals,depth);if(detail.get("procurementRecognitionId")!=null)linked("SUPPLY_RECOGNITION",FinanceV2Support.id(detail.get("procurementRecognitionId")),graph,required,originals,depth);if(detail.get("gainId")!=null)linked("ASSET_GAIN",FinanceV2Support.id(detail.get("gainId")),graph,required,originals,depth);if(detail.get("openingSubledgerId")!=null){var p=access.principal();var sub=one("select batch_id from fm_subledger where tenant_id=:tenant and id=:id",base(p).addValue("id",detail.get("openingSubledgerId")));linked("MIGRATION",FinanceV2Support.id(sub.get("batch_id")),graph,required,originals,depth);}}
  if(type.equals("ACCRUAL")){if(detail.get("sourceDocumentId")!=null)linked("OPERATION",FinanceV2Support.id(detail.get("sourceDocumentId")),graph,required,originals,depth);if(detail.get("openingSubledgerId")!=null){var p=access.principal();var sub=one("select batch_id from fm_subledger where tenant_id=:tenant and id=:id",base(p).addValue("id",detail.get("openingSubledgerId")));linked("MIGRATION",FinanceV2Support.id(sub.get("batch_id")),graph,required,originals,depth);}}
  if(type.equals("MIGRATION")){var file=new LinkedHashMap<String,Object>();file.put("id",id);file.put("sha256",detail.get("fileSha256"));file.put("originalName",detail.get("originalName"));original(graph,file,"MIGRATION",id,originals);}
 }
 private void linked(String type,UUID id,List<Map<String,Object>> graph,List<Map<String,Object>> required,Set<String> originals,int depth){var data=sourceDetail(type,id);required.add(Map.of("type",type,"id",id));graph.add(node(type,id,"ACTUAL_SOURCE_DOCUMENT",Objects.toString(data.get("version"),"0")+":"+FinanceArchiveSources.canonicalHash(clean(data))));collect(type,id,data,graph,required,originals,depth+1);}
 private static void original(List<Map<String,Object>> graph,Map<String,Object> file,String type,UUID source,Set<String> seen){UUID attachment=id(file.get("id"));String hash=Objects.toString(file.get("sha256"),"");if(attachment==null||!hash.matches("[a-f0-9]{64}"))throw conflict("真实原件缺少不可变编号或SHA256，不以占位附件替代");if(!seen.add(type+":"+source+":"+attachment))return;var row=node("ORIGINAL",attachment,"IMMUTABLE_ORIGINAL",hash);row.put("sourceType",type);row.put("sourceId",source);row.put("sha256",hash);row.put("originalName",file.get("originalName"));graph.add(row);}
 public FinanceEvidenceService.Download download(String type,UUID source,UUID attachment){sourceDetail(type,source);return switch(type){case "ASSET_GAIN"->gainFiles.download(source,attachment);case "INTAKE"->{if(!source.equals(attachment))throw missing();yield files.downloadIntake(source);}case "PROCUREMENT"->{var file=procurementFiles.download(source,attachment);yield new FinanceEvidenceService.Download(file.name(),file.type(),file.resource());}case "OPERATION"->operationFiles.download(source,attachment);default->throw bad("专项来源没有可直接下载的原件");};}
 public Map<String,Object> createReportSource(ReportSource in){var p=prepare();var date=month(in.month());var period=one("select status from fa_period where tenant_id=:tenant and book_id=:book and month=:month",base(p).addValue("book",in.bookId()).addValue("month",date));if(!"CLOSED".equals(period.get("status")))throw conflict("独立正式报表档案只接已关账真实三表，开放快报可在分析中独立冻结");var report=accounting.reportSnapshot(in.bookId(),in.month());if(!in.expectedReportVersion().equals(report.get("reportVersion")))throw conflict("已关账三表版本已变化，请重新读取");var bk=map(report.get("book"));UUID hotel=id(bk.get("hotelId")),company=id(bk.get("companyId"));if(hotel==null){var real=one("select hotel_id,company_id from fa_book where tenant_id=:tenant and id=:book",base(p).addValue("book",in.bookId()));hotel=id(real.get("hotel_id"));company=id(real.get("company_id"));}access.requireOrgScope(hotel);String hash=FinanceArchiveSources.canonicalHash(report);boolean salary=(p.hasPermission("*")||p.hasPermission("finance.payroll"))&&rows(report.getOrDefault("detailLedger",List.of())).stream().anyMatch(r->Objects.toString(r.get("sourceType"),"").toUpperCase(Locale.ROOT).contains("PAYROLL"));var b=base(p).addValue("id",in.requestId()).addValue("book",in.bookId()).addValue("hotel",hotel).addValue("company",company).addValue("month",date).addValue("version",in.expectedReportVersion()).addValue("hash",hash).addValue("payload",json(report)).addValue("salary",salary);var prior=jdbc.queryForList("select payload_hash from fac_report_source where tenant_id=:tenant and id=:id",b);if(!prior.isEmpty()&&!hash.equals(prior.getFirst().get("payload_hash")))throw conflict("报表归档请求号已绑定其他来源版本");jdbc.update("insert into fac_report_source(id,tenant_id,book_id,hotel_id,company_id,month,report_version,payload_hash,payload,sensitive_payroll,created_by) values(:id,:tenant,:book,:hotel,:company,:month,:version,:hash,cast(:payload as jsonb),:salary,:actor) on conflict(tenant_id,book_id,month,report_version,payload_hash) do nothing",b);UUID id=jdbc.queryForObject("select id from fac_report_source where tenant_id=:tenant and book_id=:book and month=:month and report_version=:version and payload_hash=:hash",b,UUID.class);audit.record("FINANCE_CLOSED_REPORT_SOURCE_FROZEN","FAC_REPORT_SOURCE",id,json(Map.of("month",in.month(),"reportVersion",in.expectedReportVersion())));return resolve("BOOK_REPORT",id);}
 private Map<String,Object> bookReport(TenantPrincipal p,UUID id){var row=one("select * from fac_report_source where tenant_id=:tenant and id=:id",base(p).addValue("id",id));access.requireOrgScope(FinanceV2Support.id(row.get("hotel_id")));if(Boolean.TRUE.equals(row.get("sensitive_payroll")))access.requirePermission("finance.payroll");accounting.reportSnapshot(FinanceV2Support.id(row.get("book_id")),YearMonth.from(((java.sql.Date)row.get("month")).toLocalDate()).toString());var payload=map(row.get("payload"));if(!FinanceArchiveSources.canonicalHash(payload).equals(row.get("payload_hash")))throw conflict("已关账报表来源指纹不符，请停止调阅并核对备份");var result=output(row);result.remove("payload");result.put("report",payload);result.put("status","CLOSED_REPORT_SOURCE");return result;}
 public Map<String,Object> available(String type,UUID hotel){var p=prepare();if(hotel!=null)access.requireOrgScope(hotel);String sql=switch(type){case "SUPPLY_RECOGNITION"->"select id from fs_recognition where tenant_id=:tenant";case "ASSET_CARD"->"select id from fs_asset_card where tenant_id=:tenant";case "ACCRUAL"->"select id from far_plan where tenant_id=:tenant";case "ASSET_GAIN"->"select id from fs_asset_gain where tenant_id=:tenant";case "BOOK_REPORT"->"select id from fac_report_source where tenant_id=:tenant";default->throw bad("请选择真实专项来源类型");};sql+=" and (:tenantScope or hotel_id in (:scopes)) and (cast(:hotel as uuid) is null or hotel_id=:hotel) order by id limit 201";var result=new ArrayList<Map<String,Object>>();for(UUID id:jdbc.queryForList(sql,base(p).addValue("hotel",hotel),UUID.class)){try{var source=sourceDetail(type,id);result.add(Map.of("id",id,"title",Objects.toString(source.get("title"),Objects.toString(source.get("assetCode"),type+" · "+id)),"sourceType",type,"hotelId",source.get("hotelId"),"companyId",source.get("companyId")));}catch(AccessDeniedException denied){}catch(ResponseStatusException denied){if(!Set.of(400,403,404,409).contains(denied.getStatusCode().value()))throw denied;}}return Map.of("items",result.stream().limit(200).toList(),"windowLimit",200,"hasMore",result.size()>200);}
 public Map<String,Object> reportChoices(){var p=prepare();access.requireAnyPermission("finance.read","finance.accounting.read","finance.accounting.write","finance.accounting.review","finance.accounting.post","finance.accounting.close");var result=new ArrayList<Map<String,Object>>();for(var row:jdbc.queryForList("select b.id book_id,b.name,b.hotel_id,b.company_id,period.month from fa_book b join fa_period period on period.tenant_id=b.tenant_id and period.book_id=b.id where b.tenant_id=:tenant and period.status='CLOSED' and period.close_snapshot is not null and (:tenantScope or b.hotel_id in (:scopes)) order by period.month desc,b.name limit 200",base(p))){var month=YearMonth.from(((java.sql.Date)row.get("month")).toLocalDate()).toString();var report=accounting.reportSnapshot(id(row.get("book_id")),month);row.put("month",month);row.put("reportVersion",report.get("reportVersion"));result.add(output(row));}return Map.of("items",result);}
 public Map<String,Object> fromEvent(Map<String,Object> event){var m=map(event.get("metadata"));if(m.get("assetId")!=null)return Map.of("type","ASSET_CARD","id",id(m.get("assetId")));if(m.get("planId")!=null)return Map.of("type","ACCRUAL","id",id(m.get("planId")));String table=Objects.toString(m.get("businessTable"),"");if(Set.of("ft_tax_accrual","ft_tax_payment").contains(table)&&m.get("returnId")!=null)return Map.of("type","TAX_RETURN","id",id(m.get("returnId")));UUID source=id(m.get("businessId"));if(source==null)return Map.of();String type=switch(table){case "fs_recognition"->"SUPPLY_RECOGNITION";case "fs_asset_event"->"ASSET_EVENT";case "fs_asset_gain"->"ASSET_GAIN";case "far_run"->"ACCRUAL_RUN";default->"";};if(type.equals("ASSET_EVENT")){var row=one("select asset_id from fs_asset_event where tenant_id=:tenant and id=:id",base(access.principal()).addValue("id",source));return Map.of("type","ASSET_CARD","id",row.get("asset_id"));}if(type.equals("ACCRUAL_RUN")){var row=one("select plan_id from far_run where tenant_id=:tenant and id=:id",base(access.principal()).addValue("id",source));return Map.of("type","ACCRUAL","id",row.get("plan_id"));}return type.isEmpty()?Map.of():Map.of("type",type,"id",source);}
 private static Map<String,Object> node(String type,UUID id,String relation,String version){var row=new LinkedHashMap<String,Object>();row.put("type",type);row.put("id",id);row.put("relation",relation);row.put("version",version);return row;}
 private static Object clean(Object value){if(value instanceof Map<?,?> map){var result=new LinkedHashMap<String,Object>();map.forEach((k,v)->{if(!Set.of("objectKey","object_key","fileBytes","file_bytes").contains(k.toString()))result.put(k.toString(),clean(v));});return result;}if(value instanceof Collection<?> list)return list.stream().map(FinanceArchiveExtendedSources::clean).toList();return value;}
}
